using Dip.Application.Abstractions.Persistence; using Dip.Application.Abstractions.Time; using Dip.Application.Features.Quality; using Dip.Domain.Entities; using Dip.Domain.Enums; using Dip.Domain.ValueObjects; using Dip.Shared.Contracts.Collectors; namespace Dip.Application.Features.Collectors; public sealed record CollectorReportResult(Guid PipelineRunId,string PipelineStatus,QualityGateResultDto QualityGate); public sealed class CollectorReportService{private readonly IProjectRepository _p;private readonly IPipelineRunRepository _r;private readonly IMetricRepository _m;private readonly IQualityIssueRepository _i;private readonly IUnitOfWork _u;private readonly ISystemClock _c;private readonly QualityGateEvaluator _q;public CollectorReportService(IProjectRepository p,IPipelineRunRepository r,IMetricRepository m,IQualityIssueRepository i,IUnitOfWork u,ISystemClock c,QualityGateEvaluator q){_p=p;_r=r;_m=m;_i=i;_u=u;_c=c;_q=q;} public async Task<CollectorReportResult>ProcessAsync(CollectorReport report,CancellationToken ct){var project=await _p.GetByIdAsync(report.ProjectId,ct)??throw new KeyNotFoundException($"Project {report.ProjectId} not found.");var run=new PipelineRun(Guid.NewGuid(),project.Id,new CommitSha(report.CommitSha),report.CollectorType,report.CollectorVersion,report.StartedAt);run.Start(report.StartedAt);if(report.Status.Equals("succeeded",StringComparison.OrdinalIgnoreCase))run.Complete(report.FinishedAt);else run.Fail($"Collector status: {report.Status}",report.FinishedAt);var metrics=report.Metrics.Select(x=>new Metric(Guid.NewGuid(),run.Id,x.Name,x.Value,x.Unit,x.BaselineValue)).ToArray();var issues=report.Issues.Select(x=>new QualityIssue(Guid.NewGuid(),project.Id,run.Id,x.Category,Enum.TryParse<Severity>(x.Severity,true,out var s)?s:Severity.Info,x.Title,x.Description,x.Source,_c.UtcNow)).ToArray();var gate=_q.Evaluate(metrics,issues);await _r.AddAsync(run,ct);await _m.AddRangeAsync(metrics,ct);await _i.AddRangeAsync(issues,ct);await _u.SaveChangesAsync(ct);return new(run.Id,run.Status.ToString(),gate);}}